"""Python half of the vault round-trip test (go/internal/vault/python_test.go).

Opens a vault that Go wrote/rotated with the REAL Python VaultManager and
reports, as JSON on stdout:

  * chain_before:  verify_audit_chain() before Python touches the vault;
  * reads:         for every expected (namespace, name, version), sha256 of
                   the plaintext Python leases, or the exception class name;
  * imported:      whether import_vault() of the Go export succeeded;
  * chain_after_import, reads_after_import;
  * wrote:         Python then writes one secret (python/written, "from-python");
  * chain_final:   verify_audit_chain() after all Python writes;
  * export_path:   Python's export_vault() output, for Go to import back.

Usage: python pyroundtrip.py VAULT_DIR MASTER_FILE EXPECT_JSON GO_EXPORT OUT_EXPORT

All key material here is throwaway test data generated by the Go test.
"""

import hashlib
import json
import sys

from rgt_vault.providers.base import MasterSecretProvider
from rgt_vault.vault import VaultManager

POLICY = """rules:
  - effect: allow
    agent: "*"
    namespace: "*"
    purpose: "*"
    action: "*"
  - effect: deny
    agent: intruder
    action: read
"""


class FileMaster(MasterSecretProvider):
    def __init__(self, path):
        self.path = path

    def get_secret(self):
        with open(self.path, "rb") as f:
            return f.read()


def read_all(vm, expect):
    out = []
    for e in expect:
        try:
            with vm.lease_secret(
                e["name"], "ci-bot", e["namespace"], "python-roundtrip", version=e["version"] or None
            ) as buf:
                out.append(hashlib.sha256(bytes(buf)).hexdigest())
        except Exception as exc:  # report the class, compare in Go
            out.append(type(exc).__name__)
    return out


def main():
    vault_dir, master, expect_path, go_export, out_export = sys.argv[1:6]
    with open(expect_path) as f:
        expect = json.load(f)
    vm = VaultManager(
        db_path=f"{vault_dir}/vault.db", master_provider=FileMaster(master), policy_yaml=POLICY, rate_limit=100000
    )
    report = {"vault_id": vm.vault_id, "key_epoch": vm.key_epoch}
    report["chain_before"] = vm.verify_audit_chain()
    report["reads"] = read_all(vm, expect)
    with open(go_export, "rb") as f:
        payload = f.read()
    vm.import_vault(payload)
    report["imported"] = True
    report["chain_after_import"] = vm.verify_audit_chain()
    report["reads_after_import"] = read_all(vm, expect)
    vm.set_secret("written", "from-python", namespace="python", agent="system")
    report["chain_final"] = vm.verify_audit_chain()
    with open(out_export, "wb") as f:
        f.write(vm.export_vault())
    report["export_path"] = out_export
    print(json.dumps(report))


if __name__ == "__main__":
    main()
